// Hand-authored, NOT generated by scripts/scanVariables.mjs — same reasoning
// as coverFields.ts/page02Fields.ts/page07Fields.ts for the fixed text nodes.
// Pricing cards are a genuine repeatable collection of structured records
// (not flat strings like Page 07's keywords), following the pattern this
// architecture is meant to establish for Pages 09-11: modules/variables/
// collections.ts + components/editor/CollectionPanel.tsx are generic: only
// this file's DATA SHAPE and default content are Page 08-specific.

export interface PricingCardRecord {
  id: string
  title: string
  /** Composed display string, e.g. "£999" — see parsePriceString/composePriceString for the structured (currency/amount/prefix) editing UI built on top of this one field. */
  price: string
  /** Billing description, e.g. "one-time payment" or "per month · 30 days notice" — presets available (see BILLING_TYPE_PRESETS) but always freely editable text. */
  priceSuffix: string
  /** '' = section not shown. Why this specific package fits this client — not a generic sales line. */
  whyRecommended: string
  features: string[]
  /** '' = section not shown. What changes for the client once this package is delivered. */
  expectedOutcome: string
  /** '' = section not shown. Only ever populated when real client-provided figures support a genuine calculation — never a fabricated statistic. */
  roiNote: string
  /** '' = no footer box shown, matching the template's own `cta: null` default. */
  footerNote: string
}

