export function makeBlankPricingCard(): PricingCardRecord {
  return {
    id: makeCollectionId(),
    title: 'New Package',
    price: '£0',
    priceSuffix: 'one-time payment',
    whyRecommended: '',
    features: ['New feature'],
    expectedOutcome: '',
    roiNote: '',
    footerNote: '',
  }
}

/**
 * Backfills `whyRecommended`/`expectedOutcome`/`roiNote` onto cards stored
 * before these fields existed — `parseCollection` is a generic
 * `JSON.parse` with no shape validation, so an older `page08.cards` blob
 * comes back with these three genuinely `undefined` at runtime despite the
 * `PricingCardRecord` type saying `string`. The Editor's own sidebar reads
 * these fields directly (unlike the live/client-facing render, which
 * DOM-patches text onto an always-complete `DEFAULT_CARDS` shape and never
 * hits this gap) — call this right after parsing stored cards, before
 * using them as real `PricingCardRecord[]`.
 */
export function normalizePricingCards(cards: Partial<PricingCardRecord>[]): PricingCardRecord[] {
  return cards.map((c) => ({
    id: c.id ?? makeCollectionId(),
    title: c.title ?? '',
    price: c.price ?? '',
    priceSuffix: c.priceSuffix ?? '',
    whyRecommended: c.whyRecommended ?? '',
    features: c.features ?? [],
    expectedOutcome: c.expectedOutcome ?? '',
    roiNote: c.roiNote ?? '',
    footerNote: c.footerNote ?? '',
  }))
}

// ─── Structured pricing helpers ────────────────────────────────────────────
// The stored field stays a single composed string (`price`) — no schema
// fragmentation — while the editor UI offers structured currency/amount/
// prefix controls on top of it, satisfying "support currency, amount,
// prefix, suffix" without duplicating the value across multiple stored
// fields that could drift out of sync with each other.

export const CURRENCY_PRESETS = ['£', '$', '€'] as const

export interface ParsedPrice {
  prefix: string
  currency: string
  amount: string
}

const PRICE_PATTERN = /^([^\d£$€]*)([£$€]?)(.*)$/

export function parsePriceString(price: string): ParsedPrice {
  const match = PRICE_PATTERN.exec(price)
  if (!match) return { prefix: '', currency: '', amount: price }
  const [, prefix, currency, amount] = match
  return { prefix, currency, amount }
}

export function composePriceString(parsed: ParsedPrice): string {
  return `${parsed.prefix}${parsed.currency}${parsed.amount}`
}

