// ─── Combination box derivation ────────────────────────────────────────────
// The frozen template's "combination box" (page08.block5/6/7/9/10/11) shows
// two packages combined — "A + B = outcome" — as plain hardcoded text,
// completely disconnected from the `cards` prop above it. Rather than have
// AI generate these six fields independently (real risk: it disagreeing
// with whatever the actual cards say, exactly the stale-pricing bug found
// earlier), they are always ALGORITHMICALLY COPIED from whichever two real
// cards are flagged as recommended/complementary — AI only picks which two
// cards those are (see recommendedCardId/complementaryCardId on
// ProposalContentPage08), never the text itself.

export interface ComboBoxCardFields {
  id: string
  title: string
  price: string
  priceSuffix: string
}

export interface ComboBoxFields {
  block5: string
  block6: string
  block7: string
  block9: string
  block10: string
  block11: string
}

/** Defaults to cards[0]/cards[1] whenever the given ids are missing, invalid, or (for complementary) the same as the recommended card — so the combo box always has two distinct real packages to show. */
export function deriveComboBoxFields(
  cards: ComboBoxCardFields[],
  recommendedCardId: string,
  complementaryCardId: string
): ComboBoxFields {
  const recommended = cards.find((c) => c.id === recommendedCardId) ?? cards[0]
  const complementary =
    cards.find((c) => c.id === complementaryCardId && c.id !== recommended?.id) ??
    cards.find((c) => c.id !== recommended?.id) ??
    cards[1]

  return {
    block5: recommended?.title ?? '',
    block6: recommended?.price ?? '',
    block7: recommended?.priceSuffix ?? '',
    block9: complementary?.title ?? '',
    block10: complementary?.price ?? '',
    block11: complementary?.priceSuffix ?? '',
  }
}

// ─── Investment split derivation (Page 07) ─────────────────────────────────
// Page 07's "Where Your Investment Goes" donut chart shows each real Page 08
// package's share of the total — computed here, deterministically, from
// live card prices. Never AI-generated (unlike everything else Page 07
// shows), for the same reason the combo box above is algorithmic: a
// separately-stored/AI-authored split would silently disagree with the
// actual cards the moment either one is edited. Billing cadence (one-time
// vs monthly) is ignored when summing, matching the combo box's own
// established precedent of combining prices regardless of suffix.

export interface InvestmentSplitSegment {
  id: string
  title: string
  price: string
  percent: number
}

/** Returns [] when fewer than 2 cards have a parseable, positive numeric price — a single-package proposal (or one with unpriced/TBC cards) has nothing meaningful to split. */
export function deriveInvestmentSplit(cards: { id: string; title: string; price: string }[]): InvestmentSplitSegment[] {
  const withAmount = cards
    .map((c) => {
      const amount = parseFloat(parsePriceString(c.price).amount.replace(/,/g, ''))
      return { ...c, amount: Number.isFinite(amount) ? amount : 0 }
    })
    .filter((c) => c.amount > 0)

  if (withAmount.length < 2) return []
  const total = withAmount.reduce((sum, c) => sum + c.amount, 0)
  if (total <= 0) return []

  return withAmount.map((c) => ({
    id: c.id,
    title: c.title,
    price: c.price,
    percent: Math.round((c.amount / total) * 100),
  }))
}

const CARD_COUNT_WORDS = ['Zero', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten']

/** Derives page08.description's package count from the real `cards` array — the frozen template's default text hardcodes "Three ways", which silently goes wrong the moment fewer or more than 3 packages are generated. Keeping this a plain derivation (not an AI-generated field) means it can never disagree with how many cards are actually on the page. */
export function derivePackagesDescription(cardCount: number): string {
  const word = CARD_COUNT_WORDS[cardCount] ?? String(cardCount)
  const ways = cardCount === 1 ? 'way' : 'ways'
  return `${word} ${ways} to close the gap. We will tell you which one actually moves the needle.`
}

